/** Game-dev search landing pages that open the Studio (/game/studio/).
 *
 * Two kinds of page, both rendered by tools/game-landing-build.mjs:
 *  - GAME_INTENT_PAGES: an existing game route (e.g. /sprite-slicer/) whose job the Studio now
 *    does. The route becomes a landing page; the old Lab UI stays at <route>/classic/ (noindex).
 *  - GAME_KEYWORD_PAGES: new search-intent pages (/game/aseprite-to-godot/ …). They are ordinary
 *    src/landings.js entries (own canonical, inherit the base intent's indexing decision) with a
 *    `studio` block, so the build renders them with the same game layout.
 *
 * Every sentence here describes shipped behaviour. The numbers and verification labels come from
 * docs/STUDIO-SPRITE.md, docs/STUDIO-PACK.md, docs/STUDIO-PACK-H2H.md and docs/STUDIO-TILE.md; if
 * one of those changes, change the copy with it. Dependency-free (static build, browser, tests). */
import {GAME_LAB_PAGES,LAB_KINDS} from './game-seo-labs.js';
import {GAME_MORE_KEYWORD_PAGES} from './game-seo-more.js';
const L=(en,ko,ja)=>({en,ko,ja});
export const GAME_HUB_PATH='game';
export const STUDIO_ROUTE='game/studio';

